import { z } from "zod"

export const LOGO_TYPES = ["image/png", "image/jpeg", "image/webp"]
export const MAX_LOGO_BYTES = 512 * 1024
export const MAX_APP_NAME_LENGTH = 20

/** The branding saved for everyone; a null name or logo means the app's own. */
export type Branding = {
  appName: string | null
  showAppName: boolean
  /** A URL, or a file picked here that the page keeps without uploading it. */
  logo: string | File | null
}

/** `logo` is a new file, null to remove the saved one, or undefined to keep it. */
export type BrandingValues = {
  appName: string
  showAppName: boolean
  logo: File | null | undefined
}

export const DEFAULT_BRANDING: Branding = {
  appName: null,
  showAppName: true,
  logo: null,
}

export const logoSchema = z
  .custom<File | null | undefined>(
    (value) => value === undefined || value === null || value instanceof File
  )
  .superRefine((file, context) => {
    if (!(file instanceof File)) return
    if (!LOGO_TYPES.includes(file.type)) {
      context.addIssue({
        code: "custom",
        message: "Choose a PNG, JPEG or WebP image.",
      })
    } else if (file.size > MAX_LOGO_BYTES) {
      context.addIssue({
        code: "custom",
        message: "Choose an image of at most 512 KB.",
      })
    }
  })

export const brandingSchema = (saved: Branding) =>
  z.object({
    appName: z
      .string()
      .trim()
      // A longer name saved before the limit stays allowed until it is changed.
      .refine(
        (name) => name.length <= MAX_APP_NAME_LENGTH || name === saved.appName,
        "Use at most 20 characters, so the name fits the sidebar."
      ),
    showAppName: z.boolean(),
    logo: logoSchema,
  })

export function toBrandingValues(saved: Branding): BrandingValues {
  return {
    appName: saved.appName ?? "",
    showAppName: saved.showAppName,
    logo: undefined,
  }
}

/** The branding once `values` are saved over `saved`. */
export function applyBranding(
  saved: Branding,
  values: BrandingValues
): Branding {
  return {
    appName: values.appName.trim() || null,
    showAppName: values.showAppName,
    logo: values.logo === undefined ? saved.logo : values.logo,
  }
}

export function isBrandingChanged(values: BrandingValues, saved: Branding) {
  const next = applyBranding(saved, values)
  return (
    next.appName !== saved.appName ||
    next.showAppName !== saved.showAppName ||
    next.logo !== saved.logo
  )
}

export const isBrandingDefault = (saved: Branding) =>
  saved.logo === null && saved.appName === null && saved.showAppName

import type { ReactNode } from "react"

type BrandingPreviewProps = {
  appName: string
  /** Shown when `appName` is empty, e.g. "OpenLMIS". */
  defaultAppName: string
  logoUrl: string
  showAppName: boolean
}

function PreviewItem({
  caption,
  children,
}: {
  caption: string
  children: ReactNode
}) {
  return (
    <figure className="flex min-w-0 flex-col gap-2">
      <figcaption className="text-xs text-muted-foreground">
        {caption}
      </figcaption>
      <div
        aria-hidden="true"
        className="flex h-32 items-center justify-center rounded-xl border bg-muted/40 p-4"
      >
        {children}
      </div>
    </figure>
  )
}

/** The branding as it lands in the browser tab, the sidebar and the sign-in page. */
export function BrandingPreview({
  appName,
  defaultAppName,
  logoUrl,
  showAppName,
}: BrandingPreviewProps) {
  const name = appName.trim() || defaultAppName

  return (
    <section
      aria-labelledby="branding-preview-title"
      className="flex flex-col gap-3"
    >
      <h2 className="text-sm font-medium" id="branding-preview-title">
        Preview
      </h2>
      <div className="grid gap-3 @xl/main:grid-cols-3">
        <PreviewItem caption="Browser Tab">
          <div className="flex max-w-full min-w-0 items-center gap-2 rounded-lg border bg-background px-3 py-1.5 text-sm shadow-xs">
            {/* oxlint-disable-next-line next/no-img-element -- items are framework-neutral, and the logo may be a local object URL */}
            <img
              alt=""
              className="size-4 shrink-0 object-contain"
              src={logoUrl}
            />
            <span className="truncate" dir="auto">
              {name}
            </span>
          </div>
        </PreviewItem>
        <PreviewItem caption="Sidebar">
          <div className="flex w-full min-w-0 items-center gap-2 rounded-lg border bg-sidebar px-3 py-2 text-sidebar-foreground shadow-xs">
            {/* oxlint-disable-next-line next/no-img-element -- items are framework-neutral, and the logo may be a local object URL */}
            <img
              alt=""
              className={
                showAppName
                  ? "h-8 max-w-24 shrink-0 object-contain"
                  : "h-6 max-w-44 object-contain"
              }
              src={logoUrl}
            />
            {showAppName && (
              <span className="truncate text-sm font-semibold" dir="auto">
                {name}
              </span>
            )}
          </div>
        </PreviewItem>
        <PreviewItem caption="Sign-In Page">
          <div className="flex min-w-0 flex-col items-center gap-1 text-center">
            {/* oxlint-disable-next-line next/no-img-element -- items are framework-neutral, and the logo may be a local object URL */}
            <img alt="" className="h-7 max-w-40 object-contain" src={logoUrl} />
            <p className="text-sm font-semibold">Sign In</p>
            <p className="line-clamp-2 text-xs text-muted-foreground">
              Enter your {name} credentials to continue.
            </p>
          </div>
        </PreviewItem>
      </div>
    </section>
  )
}

"use client"

import { revalidateLogic, useStore } from "@tanstack/react-form"
import { type ReactNode, useEffect, useState } from "react"

import { useAppForm } from "@/components/openlmis/form-fields/form"
import { SettingsList } from "@/components/openlmis/settings-list"

import { BrandingPreview } from "@/components/blocks/openlmis/branding-settings/branding-preview"
import {
  type Branding,
  type BrandingValues,
  brandingSchema,
  LOGO_TYPES,
  logoSchema,
  MAX_APP_NAME_LENGTH,
  toBrandingValues,
} from "@/components/blocks/openlmis/branding-settings/branding"

type BrandingFormOptions = {
  saved: Branding
  /** The page's Save button submits this form by id, and an invalid submit focuses its first error. */
  formId: string
  onSave: (values: BrandingValues) => void
}

/** The branding form, held by the page so its footer can save, cancel and see unsaved changes. */
export function useBrandingForm({
  saved,
  formId,
  onSave,
}: BrandingFormOptions) {
  return useAppForm({
    defaultValues: toBrandingValues(saved),
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: brandingSchema(saved) },
    onSubmit: ({ value }) => onSave(value),
    onSubmitInvalid: () =>
      document
        .querySelector<HTMLElement>(`#${formId} [aria-invalid="true"]`)
        ?.focus(),
  })
}

export type BrandingForm = ReturnType<typeof useBrandingForm>

/** A URL for a picked file, revoked once the file is no longer shown. */
function useObjectUrl(file: File | null) {
  const [created, setCreated] = useState<{ file: File; url: string }>()
  useEffect(() => {
    if (!file) return
    const url = URL.createObjectURL(file)
    // oxlint-disable-next-line react/set-state-in-effect -- an object URL is a browser resource, created and revoked with the file
    setCreated({ file, url })
    return () => URL.revokeObjectURL(url)
  }, [file])
  return created && created.file === file ? created.url : null
}

function useLogoUrl(
  logo: File | null | undefined,
  saved: Branding["logo"],
  defaultLogoUrl: string
) {
  // A file that fails validation keeps the saved logo on show.
  const rejected = logo instanceof File && !logoSchema.safeParse(logo).success
  const shown = logo === undefined || rejected ? saved : logo
  const file = shown instanceof File ? shown : null
  const objectUrl = useObjectUrl(file)
  if (file) return objectUrl ?? defaultLogoUrl
  return typeof shown === "string" ? shown : defaultLogoUrl
}

type BrandingSettingsProps = {
  form: BrandingForm
  saved: Branding
  formId: string
  /** The app's own name and logo, shown while nothing is set here. */
  defaultAppName: string
  defaultLogoUrl: string
  /** Locks every field while the parent saves. */
  pending?: boolean
  /** Above the fields, such as a failed save. */
  feedback?: ReactNode
}

/** App name, logo and whether the name shows beside it, with a live preview of where they appear. */
export function BrandingSettings({
  form,
  saved,
  formId,
  defaultAppName,
  defaultLogoUrl,
  pending = false,
  feedback,
}: BrandingSettingsProps) {
  const values = useStore(form.store, (state) => state.values)
  const logoUrl = useLogoUrl(values.logo, saved.logo, defaultLogoUrl)

  return (
    <div className="flex flex-col gap-6">
      {feedback}
      <form
        id={formId}
        noValidate
        onSubmit={(event) => {
          event.preventDefault()
          void form.handleSubmit()
        }}
      >
        <SettingsList>
          <form.AppField name="appName">
            {(field) => (
              <field.TextField
                description={`Up to ${MAX_APP_NAME_LENGTH} characters.`}
                disabled={pending}
                label="App Name"
                layout="row"
                maxLength={MAX_APP_NAME_LENGTH}
                placeholder={defaultAppName}
              />
            )}
          </form.AppField>
          <form.AppField name="logo" validators={{ onChange: logoSchema }}>
            {(field) => (
              <field.ImageField
                accept={LOGO_TYPES.join(",")}
                canRemove={
                  field.state.value instanceof File ||
                  (field.state.value === undefined && saved.logo !== null)
                }
                chooseLabel="Upload Logo"
                description="PNG, JPEG or WebP, up to 512 KB."
                disabled={pending}
                label="Logo"
                previewAlt="Logo"
                previewUrl={logoUrl}
                removeLabel="Remove Logo"
              />
            )}
          </form.AppField>
          <form.AppField name="showAppName">
            {(field) => (
              <field.SwitchField
                description="Turn off when the logo already shows the name."
                disabled={pending}
                label="Show Name Beside Logo"
                layout="row"
              />
            )}
          </form.AppField>
        </SettingsList>
      </form>
      <BrandingPreview
        appName={values.appName}
        defaultAppName={defaultAppName}
        logoUrl={logoUrl}
        showAppName={values.showAppName}
      />
    </div>
  )
}
